/**
 * Dashboard ApexCharts - màu nhãn số trên bar theo độ tương phản nền
 */
(function (w) {
    "use strict";

    var LIGHT_TEXT = "#ffffff";
    var DARK_TEXT = "#0d2a6b";

    function parseColor(value) {
        var hex;
        var match;
        if (!value || value === "none" || value === "transparent") {
            return null;
        }
        value = String(value).trim();
        if (value.indexOf("rgb") === 0) {
            match = value.match(/rgba?\(\s*([0-9.]+)\s*,\s*([0-9.]+)\s*,\s*([0-9.]+)/i);
            if (match) {
                return {
                    r: parseFloat(match[1]),
                    g: parseFloat(match[2]),
                    b: parseFloat(match[3])
                };
            }
            return null;
        }
        hex = value.replace("#", "");
        if (hex.length === 3) {
            hex = hex.charAt(0) + hex.charAt(0) + hex.charAt(1) + hex.charAt(1) + hex.charAt(2) + hex.charAt(2);
        }
        if (hex.length !== 6 || !/^[0-9a-fA-F]{6}$/.test(hex)) {
            return null;
        }
        return {
            r: parseInt(hex.substring(0, 2), 16),
            g: parseInt(hex.substring(2, 4), 16),
            b: parseInt(hex.substring(4, 6), 16)
        };
    }

    function getRelativeLuminance(rgb) {
        var r = rgb.r / 255;
        var g = rgb.g / 255;
        var b = rgb.b / 255;

        function channel(c) {
            if (c <= 0.03928) {
                return c / 12.92;
            }
            return Math.pow((c + 0.055) / 1.055, 2.4);
        }

        return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
    }

    function getContrastTextColor(bgColor) {
        var rgb = parseColor(bgColor);
        if (!rgb) {
            return LIGHT_TEXT;
        }
        if (getRelativeLuminance(rgb) < 0.45) {
            return LIGHT_TEXT;
        }
        return DARK_TEXT;
    }

    function getBarItemCount(options) {
        if (options.xaxis && options.xaxis.categories && options.xaxis.categories.length) {
            return options.xaxis.categories.length;
        }
        if (options.series && options.series[0] && options.series[0].data) {
            return options.series[0].data.length;
        }
        return 0;
    }

    function buildBarDataLabelColors(options) {
        var barColors = options.colors || ["#0d2a6b"];
        var series = options.series || [];
        var itemCount = getBarItemCount(options);
        var distributed = options.plotOptions && options.plotOptions.bar && options.plotOptions.bar.distributed === true;
        var stacked = options.chart && options.chart.stacked === true;
        var labelColors = [];
        var i;

        if (distributed && itemCount > 0) {
            for (i = 0; i < itemCount; i++) {
                labelColors.push(getContrastTextColor(barColors[i % barColors.length]));
            }
        } else if (stacked && series.length > 1) {
            for (i = 0; i < series.length; i++) {
                labelColors.push(getContrastTextColor(barColors[i % barColors.length]));
            }
        } else {
            for (i = 0; i < itemCount; i++) {
                labelColors.push(getContrastTextColor(barColors[0]));
            }
            if (labelColors.length === 0) {
                labelColors.push(getContrastTextColor(barColors[0]));
            }
        }
        return labelColors;
    }

    function syncBarDataLabelContrast(chartContext, options) {
        var root;
        var labelNodes;
        var barNodes;
        var labelColors;
        var i;
        var textColor;
        var bgColor;

        if (!chartContext || !options) {
            return;
        }
        root = chartContext.el;
        if (!root) {
            return;
        }
        labelNodes = root.querySelectorAll(".apexcharts-bar-series .apexcharts-datalabels text");
        if (!labelNodes || !labelNodes.length) {
            return;
        }
        barNodes = root.querySelectorAll(".apexcharts-bar-series .apexcharts-bar-area");
        labelColors = buildBarDataLabelColors(options);
        for (i = 0; i < labelNodes.length; i++) {
            bgColor = "";
            if (barNodes[i]) {
                bgColor = barNodes[i].getAttribute("fill") || "";
                if (!bgColor && barNodes[i].style) {
                    bgColor = barNodes[i].style.fill || "";
                }
            }
            if (bgColor) {
                textColor = getContrastTextColor(bgColor);
            } else {
                textColor = labelColors[i] || labelColors[i % labelColors.length] || LIGHT_TEXT;
            }
            labelNodes[i].setAttribute("fill", textColor);
            labelNodes[i].style.setProperty("fill", textColor, "important");
        }
    }

    function shouldEnhanceBarDataLabels(options) {
        var chartType;
        if (!options || options.isEmpty) {
            return false;
        }
        chartType = options.chart && options.chart.type ? options.chart.type : "";
        if (chartType !== "bar") {
            return false;
        }
        if (!options.dataLabels || options.dataLabels.enabled === false) {
            return false;
        }
        return true;
    }

    function enhanceBarDataLabels(options) {
        var prevEvents;
        var prevMounted;
        var prevUpdated;

        if (!shouldEnhanceBarDataLabels(options)) {
            return options;
        }
        options.dataLabels.style = options.dataLabels.style || {};
        options.dataLabels.style.colors = buildBarDataLabelColors(options);

        if (!options.chart) {
            options.chart = {};
        }
        prevEvents = options.chart.events || {};
        prevMounted = prevEvents.mounted;
        prevUpdated = prevEvents.updated;

        options.chart.events = {
            mounted: function (chartContext, config) {
                syncBarDataLabelContrast(chartContext, options);
                if (typeof prevMounted === "function") {
                    prevMounted(chartContext, config);
                }
            },
            updated: function (chartContext, config) {
                syncBarDataLabelContrast(chartContext, options);
                if (typeof prevUpdated === "function") {
                    prevUpdated(chartContext, config);
                }
            }
        };
        return options;
    }

    w.DashboardChartUtils = {
        getContrastTextColor: getContrastTextColor,
        buildBarDataLabelColors: buildBarDataLabelColors,
        enhanceBarDataLabels: enhanceBarDataLabels,
        syncBarDataLabelContrast: syncBarDataLabelContrast
    };
}(window));

