.page-wrapper .page-content .apexcharts-canvas,
.page-wrapper .page-content .apexcharts-text,
.page-wrapper .page-content .apexcharts-title-text,
.page-wrapper .page-content .apexcharts-legend-text,
.page-wrapper .page-content .apexcharts-tooltip,
.page-wrapper .page-content .apexcharts-xaxis-label,
.page-wrapper .page-content .apexcharts-yaxis-label {
    font-family: var(--title-font) !important;
}

/* Nhãn số trên bar: màu do JS set theo độ tương phản nền (dashboard-chart-utils.js) */
.page-wrapper .page-content .apexcharts-bar-series .apexcharts-datalabels text,
.page-wrapper .page-content .apexcharts-bar-series .apexcharts-data-labels text {
    fill: inherit;
}

